// Each block handles a tile of output spatial positions (Threads * PVec)
// for CcPerBlock output channels of one batch element.
// Weights for the CcPerBlock channels (all C_in*KH*KW taps) are staged in
// shared memory once per block, then reused across all output positions.
template <typename T>
__global__ void conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C_in, int H, int Win,
    int C_out, int KH, int KW,
    int stride, int padding,
    int Hout, int Wout)
